*/
scwin.init_conds = async function () {
    const binds = [{ id: "img_116", fn: function(){ return ((dlt_subcomList.getCellData(0, "isuInstTp") ?? (() => { throw new Error("unresolved:" + "subcomList.isuInstTp"); })()) === '1'); } }, { id: "img_118", fn: function(){ return ((dlt_subcomList.getCellData(0, "isuInstTp") ?? (() => { throw new Error("unresolved:" + "subcomList.isuInstTp"); })()) === '2'); } }, { id: "img_120", fn: function(){ return ((dlt_subcomList.getCellData(0, "isuInstTp") ?? (() => { throw new Error("unresolved:" + "subcomList.isuInstTp"); })()) === '3'); } }, { id: "img_122", fn: function(){ return ((dlt_subcomList.getCellData(0, "isuInstTp") ?? (() => { throw new Error("unresolved:" + "subcomList.isuInstTp"); })()) === '4'); } }, { id: "img_124", fn: function(){ return ((dlt_subcomList.getCellData(0, "isuInstTp") ?? (() => { throw new Error("unresolved:" + "subcomList.isuInstTp"); })()) === '5'); } }, { id: "img_126", fn: function(){ return ((dlt_subcomList.getCellData(0, "isuInstTp") ?? (() => { throw new Error("unresolved:" + "subcomList.isuInstTp"); })()) === '6'); } }, { id: "ipt_comNm", fn: function(){ return ((dlt_subcomList.getCellData(0, "isuInstTp") ?? (() => { throw new Error("unresolved:" + "subcomList.isuInstTp"); })()) === '1'); } }, { id: "ipt_comNm_2", fn: function(){ return ((dlt_subcomList.getCellData(0, "isuInstTp") ?? (() => { throw new Error("unresolved:" + "subcomList.isuInstTp"); })()) === '2'); } }, { id: "ipt_comNm_3", fn: function(){ return ((dlt_subcomList.getCellData(0, "isuInstTp") ?? (() => { throw new Error("unresolved:" + "subcomList.isuInstTp"); })()) === '3'); } }, { id: "ipt_comNm_4", fn: function(){ return ((dlt_subcomList.getCellData(0, "isuInstTp") ?? (() => { throw new Error("unresolved:" + "subcomList.isuInstTp"); })()) === '4'); } }, { id: "ipt_comNm_5", fn: function(){ return ((dlt_subcomList.getCellData(0, "isuInstTp") ?? (() => { throw new Error("unresolved:" + "subcomList.isuInstTp"); })()) === '5'); } }, { id: "ipt_comNm_6", fn: function(){ return ((dlt_subcomList.getCellData(0, "isuInstTp") ?? (() => { throw new Error("unresolved:" + "subcomList.isuInstTp"); })()) === '6'); } }, { id: "c_when_107", fn: function(){ return (!(String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "subcomList" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("subcomList"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "subcomList" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("subcomList")))).length === 0)); } }, { id: "tr_111", fn: function(){ return (!(String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "subcomList" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("subcomList"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "subcomList" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("subcomList")))).length === 0)); } }, { id: "c_otherwise_149", fn: function(){ return (!((!(String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "subcomList" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("subcomList"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "subcomList" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("subcomList")))).length === 0)))); } }];
    let applied = 0;
    for (let i = 0; i < binds.length; i++) {
        const b = binds[i];
        try {
            const ok = !!b.fn();
            const comp = $c.util.getComponent(b.id);
            if (comp && comp.setStyle) { comp.setStyle("display", ok ? "" : "none"); }
            else if (comp) { if (ok) { if (comp.show) { comp.show(); } } else if (comp.hide) { comp.hide(); } }
            if (ok && b.grids) {
                for (let gi = 0; gi < b.grids.length; gi++) {
                    const gc = $c.util.getComponent(b.grids[gi]);
                    if (gc && gc.refreshGridView) { gc.refreshGridView(); }
                }
            }
            applied++;
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); }
    }
    return applied;
};

// 제너레이터 채움 — 진입점(onpageload)에서 순차 실행.
/**
 * @method
 * @name scwin.init_fillGen
 * @author Inswave
 * @date 2026. 09. 29
 * @param boxId
 * @returns
 * @hidden N
*/
scwin.init_fillGen = function (boxId) {
    // 채우지 못한 자리를 모은다(동작은 계속 — 화면은 종전과 같다).
    const genSkip = [];
    let genCleared = 0;
    const genFills = [{ genId: "c_foreach_110", entity: "dlt_subcomList", countIds: [], cells: [{ childId: "__rc1", fn: function (v, i) { return String(i + 1); } }, { childId: "ipt_comNm", fn: function (v, i) { return String(v("subcomNm")); } }, { childId: "ipt_comNm_2", fn: function (v, i) { return String(v("subcomNm")); } }, { childId: "ipt_comNm_3", fn: function (v, i) { return String(v("subcomNm")); } }, { childId: "ipt_comNm_4", fn: function (v, i) { return String(v("subcomNm")); } }, { childId: "ipt_comNm_5", fn: function (v, i) { return String(v("subcomNm")); } }, { childId: "ipt_comNm_6", fn: function (v, i) { return String(v("subcomNm")); } }] }];
    const gf = genFills;
    for (let g = 0; g < gf.length; g++) {
        const f = gf[g];
        if (boxId && f.entity !== boxId) { continue; }
        const gen = $c.util.getComponent(f.genId);
        const ds = $c.util.getComponent(f.entity);
        if (!gen || !ds || !ds.getTotalRow) { genSkip.push({ gen: f.genId, box: f.entity, why: !gen ? 'no-generator' : 'no-box' }); continue; }
        const n = ds.getTotalRow();
        if (!n) { genSkip.push({ gen: f.genId, box: f.entity, why: 'empty-box' }); continue; }
        // 멱등 — 이미 채워진 제너레이터는 건너뛴다(플래그 없이 컴포넌트 상태로 판단).
        //   단, 상자를 지정해 «다시 그리라» 고 부른 경우(데이터가 새로 담긴 때)는 비우고 다시 채운다.
        if (gen.getLength && gen.getLength() > 0) {
            if (!boxId) { continue; }
            const had = gen.getLength();
            while (gen.getLength() > 0) { gen.removeChild(); }
            genCleared += had;
        }
        let row = 0;
        const cell = function (col) { const v = ds.getCellData(row, col); return (v === undefined || v === null) ? '' : v; };
        for (let i = 0; i < n; i++) {
            row = i;
            gen.insertChild(i);
            for (let c = 0; c < f.cells.length; c++) {
                const ch = gen.getChild(i, f.cells[c].childId);
                if (!ch || !ch.setValue) { continue; }
                ch.setValue(f.cells[c].fn(cell, i));
            }
            for (let k = 0; k < f.countIds.length; k++) {
                const cn = gen.getChild(i, f.countIds[k]);
                if (cn && cn.setValue) { cn.setValue(String(i + 1)); }
            }
            // 행 조건 — 마지막 행에만 보이는 자리.
            if (f.rowConds) {
                for (let rc = 0; rc < f.rowConds.length; rc++) {
                    const rn = gen.getChild(i, f.rowConds[rc].childId);
                    if (!rn) { continue; }
                    const show = (f.rowConds[rc].kind === 'last') ? (i === n - 1) : true;
                    if (rn.setStyle) { rn.setStyle('display', show ? '' : 'none'); }
                }
            }
        }
    }
    if (genSkip.length) {
        // 우리 계측이 읽는 자리 — 화면 동작에는 영향이 없다.
        scwin.genFillSkipped = genSkip;
    }
    if (genCleared) { scwin.genFillCleared = (scwin.genFillCleared || 0) + genCleared; }
};

// dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_rowCopy
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "__rb0", fn: function () { return String((($c.session && $c.session.getUserInfo && $c.session.getUserInfo()) || {})["comAbbrv"] ?? ""); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { console.warn("[sdd] 행 복사 대상 부재: " + it.childId); continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

// [A] 초기 목록 미해결 — 진입 키 subcom 를 쓰는 tx 가 4개다(tx_fn_bascomInfoModify, tx_fn_register, tx_fn_subInfoModify, tx_fn_subInfoDelete)


// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_ctxDefaults();
        scwin.init_fillGen();
        await scwin.init_rowCopy();
        await scwin.init_conds();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil25800.onpageload' });
    }
};


