            $c.util.getComponent("ipt_regComNm").readOnly = 'true';
            ($c.util.getComponent("btnLayer") && $c.util.getComponent("btnLayer").show ? $c.util.getComponent("btnLayer").show() : console.warn('[sdd] show 대상 미해결: ' + "btnLayer"));
