/**
 * @method
 * @name scwin.chk_korean
 * @author Inswave
 * @date 2026. 09. 29
 * @param obj
 * @returns
 * @hidden N
*/
scwin.chk_korean = function (obj) {
    /* sdd-asis-lifecycle:begin chk_korean — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const objVal = obj.getValue();
    let chkYn = true;
    for (i = 0; i < objVal.length; i++) {
        if (!((objVal.charCodeAt(i) > 0x3130 && objVal.charCodeAt(i) < 0x318F) || (objVal.charCodeAt(i) >= 0xAC00 && objVal.charCodeAt(i) <= 0xD7A3))) {
            chkYn = false;
            return chkYn;
        }
    }
    return chkYn;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.checkByte
 * @author Inswave
 * @date 2026. 09. 29
 * @param _obj
 * @returns
 * @hidden N
*/
scwin.checkByte = async function (_obj) {
    /* sdd-asis-lifecycle:begin fn_CheckByte — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const standardByte = 80;
    const contnByte = $c.str.getByteLength(_obj);
    if (contnByte > standardByte) {
        await $c.win.alert(((contnByte - standardByte) / 2) + "자가 초과되었습니다. 초과된 내용은 자동삭제됩니다.\n");
        const contnValue = _obj.getValue();
        _obj.setValue($c.cm.fn_CalcContn(contnValue, standardByte));
        await scwin.checkByte(_obj);
    }
    /* sdd-asis-lifecycle:end */
};



